scwin.dataTypeFormatter = function(obj, chartType, id) {
	if (chartType === "MSLine") {
		obj.dataset[0].data = [{
			value: "0.05"
		}, {
			value: "0"
		}, {
			value: "0.07"
		}, {
			value: "0.22"
		}, {
			value: "0.11"
		}, {
			value: "0.13"
		}, {
			value: "0.06"
		}, {
			value: "0"
		}];
		return obj;
	}
};
scwin.checkValue = function() {
	var temp = document.getElementsByClassName('raphael-group-41-line')[0].getElementsByTagName("path").length;
	return temp > 9;
};
